  }
}

try {
  let response = await session.fetch(request);
  session.close();
} catch (err) {
  let e: BusinessError = err as BusinessError;
  console.error("testRcpCellular err: " + JSON.stringify(e));
  session.close();
  // 对不同错误码做处理：
  // 如果返回201，可能是没有申请ohos.permission.GET_NETWORK_INFO权限。
